<?php namespace AISEO\WooCommerce; class WC_AI_Panel { public function init() { add_action('add_meta_boxes',[$this,'add_panel']); } public function add_panel() { add_meta_box('ai_seo_panel','AI SEO Studio','[$this,"render"]','product','side'); } public function render($post) { wp_nonce_field('ai_seo_wc','ai_seo_wc_nonce'); echo '<p>'.esc_html__('Auto-detected product data. One-click generate all SEO fields.','ai-seo-studio').'</p>'; echo '<button class="button" onclick="aiWoGenerate()">Generate All</button>'; } }
